  Lemma memcmp_spec_w : forall (ra sp gp tp t0 t1 t2 s0 s1 a0w a1w a2w a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) fc (m : word -> option byte) (ls rs : list byte),
    bytes_at bsegs m (bv_unsigned a0w) ls -> bytes_at bsegs m (bv_unsigned a1w) rs -> length rs = length ls ->
    Z.of_nat (length ls) = bv_unsigned a2w -> mem_inv bsegs m ->
    evt bsegs (memcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc (bv_unsigned a0w) (bv_unsigned a1w) ls rs m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0w a1w a2w a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 AMEMCMP) fc None m (seg_rom bsegs)).
  Proof.
    intros. pose proof (bv_unsigned_in_range 64 a2w) as R. unfold bv_modulus in R. change (2 ^ Z.of_N 64) with (2^64) in R.
    pose proof (memcmp_spec (bv_unsigned a0w) (bv_unsigned a1w) ls rs ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m) as S.
    unfold wz in S. rewrite !Z_to_bv_bv_unsigned in S. replace (Z_to_bv 64 (Z.of_nat (length ls))) with a2w in S.
    2:{ symmetry. rewrite <- (Z_to_bv_bv_unsigned a2w). f_equal. lia. }
    apply S; try assumption. lia.
  Qed.

